        order = {"new": [("created_at", -1)], "name": [("name", 1)], "asc": [("price", 1)], "desc": [("price", -1)], "brand": [("brand", 1), ("name", 1)], "upd": [("updated_at", -1)]}.get(sort, [("created_at", -1)])
