        acc = await current_customer(request)
        lst = [x for x in (acc.get("addresses") or []) if x["id"] != aid]
        if lst and not any(x.get("default") for x in lst):
            lst[0]["default"] = True
        await db.customer_accounts.update_one({"id": acc["id"]}, {"$set": {"addresses": lst}})
