# -*- coding: utf-8 -*-
"""Marka sayfaları (/magaza/marka/<adres>) ve SEO şablonları.

SEO şablonu: "{urun} | {kategori} | {firma}" gibi bir kalıp. Ürüne elle yazılmış başlık/açıklama varsa o kullanılır,
yoksa şablon, şablon da boşsa eski davranış (ad · firma) sürer. Değişkenler: {urun} {kategori} {marka} {model} {fiyat} {firma}.
Marka sayfasının içeriği (açıklama, logo, SEO) panelden düzenlenir; sayfa adresi markanın adından üretilir."""
import re
import time

from fastapi import Depends, HTTPException

TPL_KEYS = ("product_title", "product_desc", "category_title", "category_desc", "brand_title", "brand_desc")
TPL_DEFAULT = {
    "product_title": "{urun} | {kategori} | {firma}",
    "product_desc": "{urun} {marka} ürününü {firma} güvencesiyle inceleyin, fiyat ve stok bilgisini görün.",
    "category_title": "{kategori} Modelleri ve Fiyatları | {firma}",
    "category_desc": "{kategori} kategorisindeki ürünleri {firma} mağazasında inceleyin.",
    "brand_title": "{marka} Ürünleri | {firma}",
    "brand_desc": "{marka} markasının tüm ürünleri {firma} mağazasında. Güncel fiyat ve stok bilgisi.",
}
_TR = str.maketrans("çğıöşüÇĞİÖŞÜ", "cgiosuCGIOSU")


def slugify(s, n=70):
    s = str(s or "").translate(_TR).lower()
    s = re.sub(r"[^a-z0-9]+", "-", s).strip("-")
    return s[:n]


def _now():
    return time.strftime("%Y-%m-%dT%H:%M:%S")


def tl(v):
    try:
        n = float(v)
    except (TypeError, ValueError):
        return ""
    if n <= 0:
        return ""
    s = ("%.2f" % n).rstrip("0").rstrip(".")
    a, _, b = s.partition(".")
    a = "{:,}".format(int(a)).replace(",", ".")
    return a + ("," + b if b else "") + " TL"


def render(tpl, vars_, limit):
    """Şablondaki {değişken}leri doldurur. Değişken boşsa o parça ve yanındaki ayraç ('|', ' - ', ' · ') atılır:
    "{urun} | {kategori} | {firma}" + kategori boş → "Ürün | Firma"."""
    parts = re.split(r"(\s*\|\s*|\s+[-–—·]\s+)", str(tpl or ""))
    out, first = "", True
    for i in range(0, len(parts), 2):
        seg = parts[i]
        for k, v in vars_.items():
            seg = seg.replace("{" + k + "}", str(v or ""))
        seg = re.sub(r"\{[a-z_]+\}", "", seg)
        seg = re.sub(r"\s{2,}", " ", seg).strip(" ,:")
        if not seg:
            continue
        sep = parts[i - 1] if i > 0 else ""
        out += ("" if first else (sep if sep.strip() else " ")) + seg
        first = False
    return out[:limit].strip()


async def templates(db):
    d = await db.app_settings.find_one({"_id": "shop_seo_tpl"}, {"_id": 0}) or {}
    return {k: str(d.get(k, "") or "").strip()[:200] for k in TPL_KEYS}


async def firma_adi(db):
    g = await db.app_settings.find_one({"_id": "global"}, {"company_name": 1}) or {}
    n = (g.get("company_name") or "").strip()
    if n:
        return n
    s = await db.app_settings.find_one({"_id": "shop_settings"}, {"title": 1}) or {}
    return (s.get("title") or "").strip()


def urun_degiskenleri(p, firma):
    return {"urun": p.get("name", ""), "kategori": p.get("category", ""), "marka": p.get("brand", ""), "model": p.get("model", ""),
            "fiyat": tl(p.get("price")), "firma": firma}


def urun_seo(p, tpl, firma):
    """Elle yazılmış değer önce; yoksa şablon; yoksa boş (çağıran eski davranışa döner)."""
    v = urun_degiskenleri(p, firma)
    title = (p.get("seo_title") or "").strip() or (render(tpl["product_title"], v, 70) if tpl["product_title"] else "")
    desc = (p.get("seo_desc") or "").strip() or (render(tpl["product_desc"], v, 170) if tpl["product_desc"] else "")
    return title, desc


async def marka_listesi(db):
    """Aktif ürünlerden marka adı → {slug, name, count}; adres benzersizdir."""
    out, seen = {}, {}
    async for r in db.shop_products.find({"active": True}, {"_id": 0, "brand": 1}):
        b = (r.get("brand") or "").strip()
        if not b:
            continue
        s = slugify(b)
        if not s:
            continue
        if s in seen and seen[s] != b:
            s = s + "-" + str(len(out))
        seen.setdefault(s, b)
        o = out.setdefault(s, {"slug": s, "name": b, "count": 0})
        o["count"] += 1
    return out


async def marka_sayfasi(db, slug):
    """Herkese açık marka bilgisi (içerik + SEO). Bulunamazsa None."""
    m = (await marka_listesi(db)).get(slug)
    if not m:
        return None
    pg = await db.shop_brand_pages.find_one({"slug": slug}, {"_id": 0}) or {}
    if pg.get("hidden"):
        return None
    tpl, firma = await templates(db), await firma_adi(db)
    v = {"marka": m["name"], "firma": firma, "kategori": "", "urun": "", "model": "", "fiyat": ""}
    title = (pg.get("seo_title") or "").strip() or (render(tpl["brand_title"], v, 70) if tpl["brand_title"] else "")
    desc = (pg.get("seo_desc") or "").strip() or (render(tpl["brand_desc"], v, 170) if tpl["brand_desc"] else "")
    return {"slug": slug, "name": m["name"], "count": m["count"], "desc": pg.get("desc", ""), "logo": pg.get("logo", ""),
            "seo_title": title or (m["name"] + " Ürünleri · " + firma).strip(" ·"), "seo_desc": desc or (pg.get("desc", "")[:160]),
            "noindex": bool(pg.get("noindex"))}


def register(api_router, db, deps):
    adm = deps["require_admin"]

    @api_router.get("/shop/seo-templates")
    async def seo_get(_: dict = Depends(adm)):
        return {"values": await templates(db), "defaults": TPL_DEFAULT,
                "vars": ["urun", "kategori", "marka", "model", "fiyat", "firma"], "firma": await firma_adi(db)}

    @api_router.put("/shop/seo-templates")
    async def seo_put(payload: dict, _: dict = Depends(adm)):
        v = {}
        for k in TPL_KEYS:
            t = str((payload.get("values") or payload).get(k, "") or "").strip()[:200]
            bad = [x for x in re.findall(r"\{([^{}]*)\}", t) if x not in ("urun", "kategori", "marka", "model", "fiyat", "firma")]
            if bad:
                raise HTTPException(422, "Bilinmeyen değişken: {" + bad[0] + "}. Kullanılabilir: {urun} {kategori} {marka} {model} {fiyat} {firma}")
            v[k] = t
        await db.app_settings.update_one({"_id": "shop_seo_tpl"}, {"$set": {**v, "updated_at": _now()}}, upsert=True)
        return {"values": v}

    @api_router.get("/shop/brand-pages")
    async def bp_list(_: dict = Depends(adm)):
        brands = await marka_listesi(db)
        pages = {p["slug"]: p async for p in db.shop_brand_pages.find({}, {"_id": 0})}
        rows = []
        for s, m in sorted(brands.items(), key=lambda x: x[1]["name"].lower()):
            p = pages.get(s, {})
            rows.append({"slug": s, "name": m["name"], "count": m["count"], "desc": p.get("desc", ""), "logo": p.get("logo", ""),
                         "seo_title": p.get("seo_title", ""), "seo_desc": p.get("seo_desc", ""), "noindex": bool(p.get("noindex")),
                         "hidden": bool(p.get("hidden"))})
        return rows

    @api_router.put("/shop/brand-pages/{slug}")
    async def bp_put(slug: str, payload: dict, _: dict = Depends(adm)):
        if slug not in await marka_listesi(db):
            raise HTTPException(404, "Marka bulunamadı")
        doc = {"desc": str(payload.get("desc", "") or "").strip()[:3000], "logo": str(payload.get("logo", "") or "").strip()[:500],
               "seo_title": str(payload.get("seo_title", "") or "").strip()[:70], "seo_desc": str(payload.get("seo_desc", "") or "").strip()[:170],
               "noindex": bool(payload.get("noindex")), "hidden": bool(payload.get("hidden")), "updated_at": _now()}
        if doc["logo"] and not re.match(r"^(https://|/)", doc["logo"]):
            raise HTTPException(422, "Logo adresi https:// ile başlamalı")
        await db.shop_brand_pages.update_one({"slug": slug}, {"$set": {"slug": slug, **doc}}, upsert=True)
        return {"ok": True, **doc, "slug": slug}

    @api_router.get("/public/shop/brands")
    async def pub_brands():
        brands = await marka_listesi(db)
        pages = {p["slug"]: p async for p in db.shop_brand_pages.find({}, {"_id": 0})}
        return [{"slug": s, "name": m["name"], "count": m["count"], "logo": (pages.get(s) or {}).get("logo", "")}
                for s, m in sorted(brands.items(), key=lambda x: x[1]["name"].lower()) if not (pages.get(s) or {}).get("hidden")]

    @api_router.get("/public/shop/brands/{slug}")
    async def pub_brand(slug: str):
        r = await marka_sayfasi(db, slug)
        if not r:
            raise HTTPException(404, "Marka bulunamadı")
        return r

files.app/meta_capi.py:
# -*- coding: utf-8 -*-
"""Meta (Facebook / Instagram) tarafı: sunucu taraflı Conversions API ve ürün kataloğu akışı.

1) Conversions API: sipariş oluşunca `Purchase` olayı sunucudan Meta'ya gider. Tarayıcıdaki pixel aynı olayı
   aynı `event_id` (sipariş numarası) ile gönderdiği için Meta ikisini tek sayar; reklam engelleyici ya da
   çerez reddi olan ziyaretçilerin siparişleri de ölçülür. Ziyaretçi pazarlama çerezini reddettiyse olay
   gönderilmez. E-posta ve telefon SHA-256 ile özetlenerek gider, düz hâliyle hiçbir yere yazılmaz.
2) Katalog akışı: /api/public/feed/meta.xml — Meta Commerce Manager'da "Zamanlanmış akış" olarak eklenir.
   Ürün, varyant, indirimli fiyat, stok ve görseller dahildir; yalnız `facebook_catalog` açıkken yayınlanır.
"""
import asyncio
import hashlib
import html as _h
import re
import time
from datetime import datetime, timezone

from fastapi import Depends, HTTPException, Request
from fastapi.responses import Response

GRAPH = "https://graph.facebook.com/v21.0"


def _istek(yontem, url, **kw):
    """Ağ çağrısı. Testler bu işlevi değiştirir."""
    import requests
    kw.setdefault("timeout", 10)
    return requests.request(yontem, url, **kw)


def _sha(v):
    v = str(v or "").strip().lower()
    return hashlib.sha256(v.encode("utf-8")).hexdigest() if v else ""


def tel_norm(p):
    d = re.sub(r"\D", "", str(p or ""))
    if d.startswith("00"):
        d = d[2:]
    if d.startswith("0"):
        d = "90" + d[1:]
    elif len(d) == 10:
        d = "90" + d
    return d


def ad_ayir(ad):
    p = str(ad or "").strip().split()
    if not p:
        return "", ""
    return p[0], (p[-1] if len(p) > 1 else "")


async def ayar(db):
    """Pixel kimliği ve API anahtarı; ikisi de varsa ve entegrasyon açıksa."""
    r = await db.yp_integrations.find_one({"id": "meta_pixel", "on": True}, {"_id": 0, "keys": 1}) or {}
    k = r.get("keys") or {}
    pid, tok = str(k.get("id") or "").strip(), str(k.get("token") or "").strip()
    if not (pid.isdigit() and tok):
        return None
    return {"pixel": pid, "token": tok, "test": str(k.get("test_code") or "").strip()}


def olay_kur(order, mk, ip, ua, host=""):
    """Purchase olayı gövdesi (Meta Conversions API biçimi)."""
    cu = order.get("customer") or {}
    fn, ln = ad_ayir(cu.get("name"))
    ud = {"client_ip_address": ip or "", "client_user_agent": ua or ""}
    for k, v in (("em", _sha(cu.get("email"))), ("ph", _sha(tel_norm(cu.get("phone")))), ("fn", _sha(fn)), ("ln", _sha(ln)),
                 ("ct", _sha(re.sub(r"\s", "", str(cu.get("city") or "")))), ("country", _sha("tr")),
                 ("external_id", _sha(order.get("account_id") or order.get("phone_key")))):
        if v:
            ud[k] = [v]
    if mk.get("fbp"):
        ud["fbp"] = str(mk["fbp"])[:120]
    if mk.get("fbc"):
        ud["fbc"] = str(mk["fbc"])[:200]
    items = order.get("items") or []
    url = str(mk.get("url") or "")[:500] or ("https://%s/magaza" % host if host else "")
    return {
        "event_name": "Purchase", "event_time": int(time.time()), "event_id": str(order.get("order_no")),
        "action_source": "website", "event_source_url": url, "user_data": ud,
        "custom_data": {"currency": "TRY", "value": round(float(order.get("total") or 0), 2), "order_id": str(order.get("order_no")),
                        "content_type": "product", "content_ids": [str(i.get("product_id") or i.get("id") or "") for i in items],
                        "contents": [{"id": str(i.get("product_id") or i.get("id") or ""), "quantity": int(i.get("qty") or 1),
                                      "item_price": round(float(i.get("price") or 0), 2)} for i in items],
                        "num_items": sum(int(i.get("qty") or 1) for i in items)},
    }


def _gonder(cfg, olay):
    body = {"data": [olay], "access_token": cfg["token"]}
    if cfg.get("test"):
        body["test_event_code"] = cfg["test"]
    r = _istek("POST", "%s/%s/events" % (GRAPH, cfg["pixel"]), json=body)
    try:
        j = r.json()
    except Exception:                                              # noqa: BLE001
        j = {}
    if r.status_code >= 400:
        return False, ((j.get("error") or {}).get("message") or "kod %s" % r.status_code)[:200]
    return True, "%s olay alındı" % j.get("events_received", 1)


async def purchase(db, order, mk, ip, ua, host=""):
    """Siparişi Meta'ya bildirir. Hiçbir hata siparişi bozmaz; sonuç entegrasyon günlüğüne yazılır."""
    try:
        if not isinstance(mk, dict) or mk.get("pz") is False:
            return None                                            # pazarlama çerezi reddedildi
        cfg = await ayar(db)
        if not cfg:
            return None
        ok, msg = await asyncio.to_thread(_gonder, cfg, olay_kur(order, mk, ip, ua, host))
        await db.yp_int_log.insert_one({"id": "mc" + str(int(time.time() * 1000)), "int": "meta_pixel",
                                        "event": "capi purchase" if ok else "capi hata", "note": ("%s · %s" % (order.get("order_no"), msg))[:300],
                                        "at": datetime.now(timezone.utc).isoformat()})
        return ok
    except Exception:                                              # noqa: BLE001
        return None


# ------------------------------------------------------------------ katalog akışı
def _x(v):
    return _h.escape(str(v if v is not None else ""), quote=False)


def feed_xml(rows, base, firma):
    items = []

    def madde(p, vid="", vlabel="", price=None, stock=None, img=None, group=""):
        slug = p.get("slug") or p["id"]
        fiyat = float(price if price is not None else p.get("price") or 0)
        eski = float(p.get("old_price") or 0)
        im = img or (p.get("images") or [""])[0]
        if im.startswith("/"):
            im = base + im
        extra = [("https:" + u if u.startswith("//") else (base + u if u.startswith("/") else u)) for u in (p.get("images") or [])[1:10]]
        var_dahil = p.get("track_stock", True)
        stok = (not var_dahil) or int(stock if stock is not None else p.get("stock", 0) or 0) > 0
        ad = p.get("name") or ""
        if vlabel:
            ad = "%s - %s" % (ad, vlabel)
        link = "%s/magaza/urun/%s" % (base, slug) + (("?v=" + vid) if vid else "")
        s = ["<item>", "<g:id>%s</g:id>" % _x(vid or p["id"]), "<g:title>%s</g:title>" % _x(ad[:150]),
             "<g:description>%s</g:description>" % _x(re.sub(r"<[^>]+>", " ", p.get("description") or p.get("short") or ad)[:5000]),
             "<g:link>%s</g:link>" % _x(link), "<g:availability>%s</g:availability>" % ("in stock" if stok else "out of stock"),
             "<g:condition>new</g:condition>"]
        if eski > fiyat > 0:
            s += ["<g:price>%.2f TRY</g:price>" % eski, "<g:sale_price>%.2f TRY</g:sale_price>" % fiyat]
        else:
            s.append("<g:price>%.2f TRY</g:price>" % fiyat)
        if im:
            s.append("<g:image_link>%s</g:image_link>" % _x(im))
        for u in extra:
            s.append("<g:additional_image_link>%s</g:additional_image_link>" % _x(u))
        s.append("<g:brand>%s</g:brand>" % _x(p.get("brand") or firma))
        if p.get("category"):
            s.append("<g:product_type>%s</g:product_type>" % _x(p["category"]))
        if p.get("gtin"):
            s.append("<g:gtin>%s</g:gtin>" % _x(p["gtin"]))
        elif p.get("sku"):
            s.append("<g:mpn>%s</g:mpn>" % _x(p["sku"]))
        if group:
            s.append("<g:item_group_id>%s</g:item_group_id>" % _x(group))
        s.append("</item>")
        items.append("".join(s))

    for p in rows:
        vs = [v for v in (p.get("variants") or []) if v.get("active", True)]
        if vs:
            for v in vs:
                madde(p, vid=str(v["id"]), vlabel=v.get("label") or "", price=v.get("price") or p.get("price"), stock=v.get("stock"),
                      img=v.get("image") or None, group=p["id"])
        else:
            madde(p)
    return ('<?xml version="1.0" encoding="UTF-8"?><rss xmlns:g="http://base.google.com/ns/1.0" version="2.0"><channel>'
            "<title>%s</title><link>%s</link><description>%s ürünleri</description>%s</channel></rss>" % (_x(firma), _x(base), _x(firma), "".join(items)))


def register(api_router, db, deps):
    adm = deps["require_admin"]

    async def firma_adi():
        g = await db.app_settings.find_one({"_id": "global"}, {"_id": 0, "company_name": 1}) or {}
        return g.get("company_name") or "Mağaza"

    @api_router.get("/public/feed/meta.xml")
    async def feed_meta(request: Request):
        r = await db.yp_integrations.find_one({"id": "facebook_catalog", "on": True}, {"_id": 1})
        if not r:
            raise HTTPException(404, "Bu besleme kapalı")
        rows = await db.shop_products.find({"active": True}, {"_id": 0}).to_list(5000)
        host = request.headers.get("x-forwarded-host") or request.headers.get("host") or ""
        return Response(feed_xml(rows, "https://" + host, await firma_adi()), media_type="application/xml; charset=utf-8")

    @api_router.get("/yp/meta")
    async def meta_durum(request: Request, _: dict = Depends(adm)):
        """Panelde gösterilecek akış adresi ve sunucu taraflı gönderim durumu."""
        host = request.headers.get("x-forwarded-host") or request.headers.get("host") or ""
        cat = await db.yp_integrations.find_one({"id": "facebook_catalog", "on": True}, {"_id": 1})
        cfg = await ayar(db)
        son = await db.yp_int_log.find({"int": "meta_pixel", "event": {"$in": ["capi purchase", "capi hata"]}}, {"_id": 0}).sort("at", -1).to_list(5)
        return {"feed_url": "https://%s/api/public/feed/meta.xml" % host, "feed_on": bool(cat), "capi_on": bool(cfg), "test_mode": bool(cfg and cfg["test"]), "son": son}

files.app/musteri_mail.py:
# -*- coding: utf-8 -*-
"""Müşteriye giden sipariş e-postaları: sipariş alındı, onaylandı, kargoya verildi, teslim edildi, iptal, iade onayı, iade ödemesi.

- Şablonlar panelden düzenlenir (konu + metin, {değişken}li). Her olay tek tek açılıp kapatılır.
- Aynı sipariş ve olay için e-posta yalnız bir kez gider (musteri_mail_log).
- E-posta adresi yoksa, SMTP girilmemişse, ya da pazaryeri/dış kaynaklı siparişse hiçbir şey gönderilmez; hata sipariş akışını bozmaz.
- Gönderim notify.send ile yapılır, Bildirim kayıtlarında (outbox) görünür."""
import re
import time

from fastapi import Depends, HTTPException

import notify

OLAYLAR = {
    "siparis_alindi": "Sipariş alındı",
    "siparis_onaylandi": "Sipariş onaylandı (ödeme alındı)",
    "kargoya_verildi": "Kargoya verildi",
    "teslim_edildi": "Teslim edildi",
    "iptal": "Sipariş iptal edildi",
    "iade_onaylandi": "İade talebi onaylandı",
    "iade_odendi": "İade ödemesi yapıldı",
}
DEGISKENLER = ["ad", "siparis_no", "tutar", "urunler", "kargo_firmasi", "takip_no", "iade_tutari", "firma"]
VARSAYILAN = {
    "siparis_alindi": {"on": True, "subject": "{firma} — {siparis_no} numaralı siparişiniz alındı",
                       "body": "Merhaba {ad},\n\nSiparişiniz alındı. Sipariş numaranız: {siparis_no}\n\n{urunler}\n\nToplam: {tutar}\n\nSiparişinizin durumu değiştikçe size yeniden e-posta göndereceğiz.\n\nTeşekkür ederiz,\n{firma}"},
    "siparis_onaylandi": {"on": True, "subject": "{firma} — {siparis_no} siparişiniz onaylandı",
                          "body": "Merhaba {ad},\n\n{siparis_no} numaralı siparişiniz onaylandı ve hazırlanmaya başlandı.\n\nToplam: {tutar}\n\nTeşekkür ederiz,\n{firma}"},
    "kargoya_verildi": {"on": True, "subject": "{firma} — {siparis_no} siparişiniz kargoya verildi",
                        "body": "Merhaba {ad},\n\n{siparis_no} numaralı siparişiniz kargoya verildi.\nKargo firması: {kargo_firmasi}\nTakip numarası: {takip_no}\n\nKargo firmasının sitesinden takip numaranızla gönderinizi izleyebilirsiniz.\n\nTeşekkür ederiz,\n{firma}"},
    "teslim_edildi": {"on": True, "subject": "{firma} — {siparis_no} siparişiniz teslim edildi",
                      "body": "Merhaba {ad},\n\n{siparis_no} numaralı siparişiniz teslim edildi. Bizi tercih ettiğiniz için teşekkür ederiz.\n\nBir sorun varsa bu e-postayı yanıtlayarak ya da bizi arayarak bize ulaşabilirsiniz.\n\n{firma}"},
    "iptal": {"on": True, "subject": "{firma} — {siparis_no} siparişiniz iptal edildi",
              "body": "Merhaba {ad},\n\n{siparis_no} numaralı siparişiniz iptal edildi.\nÖdeme yaptıysanız iade süreci hakkında size ayrıca bilgi verilecektir.\n\nSorularınız için bize ulaşabilirsiniz.\n\n{firma}"},
    "iade_onaylandi": {"on": True, "subject": "{firma} — {siparis_no} iade talebiniz onaylandı",
                       "body": "Merhaba {ad},\n\n{siparis_no} numaralı siparişinize ait iade talebiniz onaylandı.\n\n{urunler}\n\nİade tutarı: {iade_tutari}\nÜrünler bize ulaştığında ödemeniz iade edilecektir.\n\n{firma}"},
    "iade_odendi": {"on": True, "subject": "{firma} — {siparis_no} iade ödemeniz yapıldı",
                    "body": "Merhaba {ad},\n\n{siparis_no} numaralı siparişinize ait {iade_tutari} tutarındaki iade ödemeniz yapıldı. Bankanıza bağlı olarak hesabınıza yansıması birkaç iş günü sürebilir.\n\n{firma}"},
}
YABANCI_KANAL = ("trendyol", "hepsiburada", "n11", "amazon", "ciceksepeti", "pttavm", "yemeksepeti", "getir", "trendyol_go", "migros")


def tl(v):
    try:
        n = float(v)
    except (TypeError, ValueError):
        return ""
    s = ("%.2f" % n).rstrip("0").rstrip(".")
    a, _, b = s.partition(".")
    return "{:,}".format(int(a)).replace(",", ".") + ("," + b if b else "") + " TL"


def _t(v, n):
    return str(v or "").strip()[:n]


def doldur(tpl, v):
    t = str(tpl or "")
    for k, x in v.items():
        t = t.replace("{" + k + "}", str(x if x is not None else ""))
    t = re.sub(r"\{[a-z_]+\}", "", t)
    t = re.sub(r"[ \t]+\n", "\n", t)
    return re.sub(r"\n{3,}", "\n\n", t).strip()


def urun_satirlari(items):
    out = []
    for i in (items or [])[:30]:
        ad = i.get("name") or i.get("ad") or ""
        ek = i.get("vl") or i.get("variant") or ""
        out.append("• %s x %s%s — %s" % (i.get("qty") or i.get("adet") or 1, ad, (" (" + ek + ")") if ek else "", tl((i.get("price") or 0) * (i.get("qty") or 1))))
    return "\n".join(out)


async def ayarlar(db):
    d = await db.app_settings.find_one({"_id": "musteri_mail"}, {"_id": 0}) or {}
    out = {"on": bool(d.get("on")), "events": {}}
    for k, v in VARSAYILAN.items():
        o = (d.get("events") or {}).get(k) or {}
        out["events"][k] = {"on": bool(o.get("on", v["on"])), "subject": _t(o.get("subject"), 200) or v["subject"], "body": _t(o.get("body"), 4000) or v["body"]}
    return out


def vars_shop(o, firma):
    c = o.get("customer") or {}
    return {"ad": (c.get("name") or "").split(" ")[0] or "Müşterimiz", "siparis_no": o.get("order_no", ""), "tutar": tl(o.get("total")),
            "urunler": urun_satirlari(o.get("items")), "kargo_firmasi": o.get("carrier") or "—", "takip_no": o.get("tracking_no") or "—",
            "iade_tutari": tl(o.get("total")), "firma": firma}


async def gonder(db, olay, to, v, ref, kanal=""):
    """Tek e-posta. True: gönderildi. Asla istisna fırlatmaz."""
    try:
        if olay not in OLAYLAR or not to or not re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", str(to)):
            return False
        if kanal and str(kanal).lower() in YABANCI_KANAL:
            return False
        a = await ayarlar(db)
        e = a["events"][olay]
        if not a["on"] or not e["on"]:
            return False
        key = "%s:%s" % (ref, olay)
        if await db.musteri_mail_log.find_one({"key": key}, {"_id": 1}):
            return False
        cfg = await notify.get_settings(db)
        if not (cfg.get("smtp") or {}).get("host"):
            await db.musteri_mail_log.insert_one({"key": key, "olay": olay, "to": to, "status": "smtp_yok", "at": time.strftime("%Y-%m-%dT%H:%M:%S")})
            return False
        await db.musteri_mail_log.insert_one({"key": key, "olay": olay, "to": to, "status": "gonderiliyor", "at": time.strftime("%Y-%m-%dT%H:%M:%S")})
        r = await notify.send(db, "email", to, doldur(e["body"], v), doldur(e["subject"], v)[:200], kind="musteri_" + olay, ref=str(ref), cfg=cfg)
        await db.musteri_mail_log.update_one({"key": key}, {"$set": {"status": r.get("status", "")}})
        return r.get("status") == "sent"
    except Exception:                                                      # noqa: BLE001
        return False


async def firma_adi(db):
    import marka_seo
    return (await marka_seo.firma_adi(db)) or "Mağazamız"


async def shop_olay(db, olay, o):
    """shop_orders belgesi için (web sitesi siparişleri). Dış kaynaklı siparişe gönderilmez."""
    if not o or o.get("external") or o.get("market_status"):
        return False
    return await gonder(db, olay, (o.get("customer") or {}).get("email"), vars_shop(o, await firma_adi(db)), "shop:" + str(o.get("id") or o.get("order_no")))


def shop_durum_olayi(durum):
    return {"onaylandi": "siparis_onaylandi", "kargoda": "kargoya_verildi", "teslim_edildi": "teslim_edildi", "iptal": "iptal"}.get(durum)


async def yp_olay(db, olay, o, ret=None):
    """yp_orders belgesi için (panelden girilen siparişler). Pazaryeri kanalları atlanır."""
    if not o or o.get("market_no"):
        return False
    try:
        from siparis import CARGOS, _PAZAR
        if o.get("channel") in _PAZAR:                                     # pazaryeri siparişi: müşteriye pazaryeri yazar
            return False
    except Exception:                                                      # noqa: BLE001
        CARGOS = {}
    c = o.get("customer") or {}
    cg = o.get("cargo") or {}
    firma = await firma_adi(db)
    v = {"ad": (c.get("name") or "").split(" ")[0] or "Müşterimiz", "siparis_no": o.get("no", ""), "tutar": tl(o.get("total")),
         "urunler": urun_satirlari((ret or o).get("items")), "kargo_firmasi": CARGOS.get(cg.get("firm"), cg.get("firm")) or "—",
         "takip_no": cg.get("code") or cg.get("barcode") or "—", "iade_tutari": tl((ret or {}).get("refund") or o.get("total")), "firma": firma}
    return await gonder(db, olay, c.get("email"), v, "yp:" + str(o.get("id")) + (":" + ret["id"] if ret else ""), o.get("channel"))


YP_DURUM = {"onaylandi": "siparis_onaylandi", "kargoda": "kargoya_verildi", "teslim": "teslim_edildi", "iptal": "iptal"}


def register(api_router, db, deps):
    adm = deps["require_admin"]

    @api_router.get("/shop/customer-mail")
    async def cm_get(_: dict = Depends(adm)):
        cfg = await notify.get_settings(db)
        a = await ayarlar(db)
        return {**a, "labels": OLAYLAR, "vars": DEGISKENLER, "defaults": VARSAYILAN,
                "smtp_ok": bool((cfg.get("smtp") or {}).get("host")), "from_addr": (cfg.get("smtp") or {}).get("from_addr") or (cfg.get("smtp") or {}).get("user") or ""}

    @api_router.put("/shop/customer-mail")
    async def cm_put(payload: dict, _: dict = Depends(adm)):
        ev = {}
        for k in OLAYLAR:
            o = (payload.get("events") or {}).get(k) or {}
            subj, body = _t(o.get("subject"), 200), _t(o.get("body"), 4000)
            for t in (subj, body):
                bad = [x for x in re.findall(r"\{([^{}]*)\}", t) if x not in DEGISKENLER]
                if bad:
                    raise HTTPException(422, "%s: bilinmeyen değişken {%s}. Kullanılabilir: %s" % (OLAYLAR[k], bad[0], " ".join("{" + x + "}" for x in DEGISKENLER)))
            ev[k] = {"on": bool(o.get("on", True)), "subject": subj, "body": body}
        await db.app_settings.update_one({"_id": "musteri_mail"}, {"$set": {"on": bool(payload.get("on")), "events": ev, "updated_at": time.strftime("%Y-%m-%dT%H:%M:%S")}}, upsert=True)
        return await cm_get(_)

    @api_router.post("/shop/customer-mail/test")
    async def cm_test(payload: dict, _: dict = Depends(adm)):
        """Seçilen şablonu örnek siparişle yöneticinin yazdığı adrese gönderir (kayıt tutulmaz, bir kez kuralına takılmaz)."""
        olay, to = _t(payload.get("event"), 30), _t(payload.get("to"), 120)
        if olay not in OLAYLAR:
            raise HTTPException(422, "Olay geçersiz")
