def cta(X, second='tel', cls=''):
    a = f'<a class="btn" href="#randevu">{X.r.get("cta", "Randevu al")} {ic("ar", 18)}</a>'
    if second == 'tel':
        b = f'<a class="btn o" href="tel:+{TELRAW}">{ic("tel", 18)} {TEL}</a>'
    elif second == 'wa':
        b = f'<a class="btn o" href="https://wa.me/{TELRAW}">{ic("wa", 18)} WhatsApp</a>'
    else:
