def _brands(rows):
    seen = []
    for r in rows:
        for b in r[2].split(','):
            b = b.strip()
            if b and '(' not in b and b not in seen and b not in ('Tüm markalar', 'Model seçimiyle'):
                seen.append(b)
    return seen[:10]


