        drawer = drawer.replace('Sadece parça gönderin', 'Standart teslimat').replace('Montajı kendim yapacağım / ustam var.', 'Siparişim adresime gönderilsin.')
        drawer = _re.sub(r'<p class="nt" style="margin-bottom:12px">Parçayı kendiniz mi.*?</p>', '<p class="nt" style="margin-bottom:12px">Teslimat seçeneğinizi onaylayın; ürün hazırlandığında size bilgi verilir.</p>', drawer)
        drawer = drawer.replace('3 Servis', '3 Teslimat')
    fab = f'<button class="crt-fab" data-cart aria-label="Sepeti aç">{ic("bx", 20)} Sepet <i data-ccount>0</i></button>'
    X.shop_data = data
    return (f'<section class="sec shp{cls}" id="urunler"><div class="w">{head}{bar}{catb}<div class="pg" id="pg"></div></div>'
            f'<script>window.__SHOPCFG={json.dumps(X.r.get("shopcfg", CFG), ensure_ascii=False)};window.__SHOP={data};window.__SHOPIC={json.dumps(ic(X.c["ico"], 54, 1.4))};</script></section>{drawer}{fab}')


def hero_shop(X):
